import{_ as e,o as a,c as l,a0 as d}from"./chunks/framework.KrHIIkJd.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1786781926000}'),i={name:"guide/quick-start.md"};function r(s,t,o,n,c,h){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>skills-hub 是一个 Windows 桌面应用(Rust + Tauri v2),统一管理本机 8 个 AI agent 的 skills。</p><h2 id="支持的管理对象" tabindex="-1">支持的管理对象 <a class="header-anchor" href="#支持的管理对象" aria-label="Permalink to &quot;支持的管理对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Agent</th><th>默认 skills 目录</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>~/.claude/skills</code></td></tr><tr><td>Codex</td><td><code>~/.codex/skills</code></td></tr><tr><td>Grok</td><td><code>~/.grok/skills</code></td></tr><tr><td>Pi</td><td><code>~/.pi/agent/skills</code></td></tr><tr><td>Cursor</td><td><code>~/.cursor/skills</code></td></tr><tr><td>Trae</td><td><code>~/.trae/skills</code></td></tr><tr><td>Qoder</td><td><code>~/.qoder/skills</code></td></tr><tr><td>Universal</td><td><code>~/.agents/skills</code></td></tr></tbody></table><p>目录不存在不会报错,只是该 agent 显示 0 个技能;也可以在设置里覆盖任意路径。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>到 <a href="/skills-hub/download.html">下载</a> 页获取最新的 <code>skills-hub_x.x.x_x64-setup.exe</code> 安装包。</li><li>运行安装包,按向导完成安装(无需管理员权限)。</li><li>启动应用,首次会自动扫描全部 agent 目录。</li></ol><div class="tip custom-block"><p class="custom-block-title">系统要求</p><p>Windows 10/11。「全局质感背景」的窗口亚克力透明需要 Windows 10/11,且系统「设置 → 个性化 → 颜色 → 透明度效果」处于开启状态。</p></div><h2 id="界面结构" tabindex="-1">界面结构 <a class="header-anchor" href="#界面结构" aria-label="Permalink to &quot;界面结构&quot;">​</a></h2><ul><li><strong>左侧图标栏</strong>:首页/设置入口,底部明暗主题切换</li><li><strong>Agent 侧栏</strong>:「全部技能」+ 8 个 agent 过滤,带计数与「未检测到」提示</li><li><strong>技能列表</strong>:搜索框(Ctrl+F)+ 技能行;行尾橙色圆点表示该技能在不同 agent 间的副本内容不一致(漂移)</li><li><strong>详情区</strong>:SKILL.md 渲染预览 / 原文编辑(CodeMirror,Ctrl+S 保存),顶部徽标切换查看不同 agent 的副本</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/skills-hub/guide/manage.html">技能管理</a>:查看、编辑、新建、删除</li><li><a href="/skills-hub/guide/command-add.html">命令添加技能</a>:一条命令从 GitHub 安装技能</li><li><a href="/skills-hub/guide/sync.html">同步</a>:把技能复制到更多 agent</li><li><a href="/skills-hub/guide/translate.html">翻译阅读</a>:DeepSeek 翻译英文技能</li><li><a href="/skills-hub/guide/settings.html">外观与设置</a>:主题、色调、质感背景、路径覆盖</li></ul>',12)])])}const g=e(i,[["render",r]]);export{k as __pageData,g as default};
